// Exactly what Home Assistant gets: five keys, timestamps ISO-8601 UTC.
const r = $input.first().json || {};
const iso = (t) => (t === null || t === undefined || t === '' ? null : new Date(t).toISOString());
return [{ json: { source: 'pr-triage', last_success: iso(r.last_success), watch_last_success: iso(r.watch_last_success), stale: r.stale === true, checked: iso(r.checked) } }];
